/**
 * env-manifest.json: the schema as plain JSON for code that cannot import
 * TypeScript (electron/main.cjs, apps/web/scripts/next.mjs and, from E4 on,
 * scripts/env.mjs and scripts/doctor.mjs). Generated by `npm run env:example`;
 * a guard test fails when the committed file is stale.
 */
import { CONVEX_SYNC_KEYS } from "./convexSync";
import { BOOL_FALSE, BOOL_TRUE } from "./parse";
import { ENV_SCHEMA } from "./schema";
import type { EnvVar, Runtime } from "./schema/types";
import { CHILD_ENV_ESCAPE_NAMES, EXTRA_PLATFORM_SECRETS, KNOWN_PROVIDER_KEYS, SCHEMA_SECRET_NAMES } from "./secrets";

export interface ManifestVar {
  name: string;
  type: EnvVar["type"];
  group: EnvVar["group"];
  runtimes: readonly Runtime[];
  doc: string;
  /** Static default as a string ("" when the var has none); derived defaults are listed in `derivedDefault`. */
  default: string | null;
  derivedDefault?: true;
  parse?: string;
  min?: number;
  max?: number;
  options?: readonly string[];
  aliases?: readonly string[];
  secret?: true;
  required?: readonly Runtime[];
  knob?: EnvVar["knob"];
  convexSystem?: true;
  deprecated?: string;
}

export interface EnvManifest {
  $comment: string;
  vars: ManifestVar[];
  /** The bool dialect (B2): unset/blank → default, these words → true/false, else default + warning. */
  bool: { true: readonly string[]; false: readonly string[] };
  convexSync: readonly string[];
  secrets: { schema: readonly string[]; extraPlatform: readonly string[]; knownProviderKeys: readonly string[]; childEnvEscape: readonly string[] };
  required: Partial<Record<Runtime, string[]>>;
}

function defaultString(def: EnvVar): { value: string | null; derived?: true } {
  if (!("default" in def) || def.default === undefined) return { value: null };
  const value = def.default as unknown;
  if (typeof value === "function") return { value: null, derived: true };
  if (typeof value === "number" && !Number.isFinite(value)) return { value: String(value) };
  return { value: String(value) };
}

export function buildManifest(): EnvManifest {
  const vars: ManifestVar[] = [];
  const required: Partial<Record<Runtime, string[]>> = {};
  for (const def of ENV_SCHEMA as readonly EnvVar[]) {
    const dflt = defaultString(def);
    const entry: ManifestVar = {
      name: def.name,
      type: def.type,
      group: def.group,
      runtimes: def.runtimes,
      doc: def.doc,
      default: dflt.value,
    };
    if (dflt.derived) entry.derivedDefault = true;
    if ("parse" in def && def.parse) entry.parse = def.parse;
    if ("min" in def && def.min !== undefined) entry.min = def.min;
    if ("max" in def && def.max !== undefined) entry.max = def.max;
    if ("options" in def) entry.options = def.options;
    if (def.aliases) entry.aliases = def.aliases;
    if (def.secret) entry.secret = true;
    if (def.required) entry.required = def.required;
    if (def.knob) entry.knob = def.knob;
    if (def.convexSystem) entry.convexSystem = true;
    if (def.deprecated) entry.deprecated = def.deprecated;
    vars.push(entry);
    for (const runtime of def.required ?? []) (required[runtime] ??= []).push(def.name);
  }
  return {
    $comment: "Generated from packages/config/src/schema by `npm run env:example`. Do not edit.",
    vars,
    bool: { true: BOOL_TRUE, false: BOOL_FALSE },
    convexSync: CONVEX_SYNC_KEYS,
    secrets: {
      schema: SCHEMA_SECRET_NAMES,
      extraPlatform: EXTRA_PLATFORM_SECRETS,
      knownProviderKeys: KNOWN_PROVIDER_KEYS,
      childEnvEscape: CHILD_ENV_ESCAPE_NAMES,
    },
    required,
  };
}

export function renderManifest(): string {
  return `${JSON.stringify(buildManifest(), null, 2)}\n`;
}
